-	dark: {
-		background: "#18191b",
-		border: "#2f2f37",
-		error: "#e54666",
-		foreground: "#fcfcfd",
-		muted: "#212225",
-		mutedForeground: "#b0b4ba",
-		primary: "#6e56cf",
-	},
-	light: {
-		background: "#f9f9fb",
-		border: "#e8e8ec",
-		error: "#e54666",
-		foreground: "#1c2024",
-		muted: "#f0f0f3",
-		mutedForeground: "#60646c",
-		primary: "#6e56cf",
