-function hexOr(
-	value: string,
-	fallback: string,
-	resolveColor: MermaidColorResolver | undefined,
-): string {
-	const resolved = resolveColor?.(value);
-	const hex = resolved ? cssColorToHex(resolved) : null;
-	return hex ?? cssColorToHex(value) ?? fallback;
