-		fontFamily: options.fontFamily ?? MERMAID_FONT_FAMILY,
-		htmlLabels: false,
-		securityLevel: "strict",
-		startOnLoad: false,
-		suppressErrorRendering: true,
-		theme: "base",
-		themeVariables: buildMermaidThemeVariables(tokens, mode, options),
